import styled from '@emotion/styled';

export const StyledHowWeDoItCardRoot = styled.div({
  width: '100%',
  minWidth: 0,
  boxSizing: 'border-box',
  height: '100%',
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',

  '& [data-testid="sub-pillar-card"]': {
    flex: 1,
    minHeight: 0,
    width: '100%',
    maxWidth: 'none',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
    cursor: 'default',
  },

  '& [data-testid="sub-pillar-card-content"]': {
    flex: 1,
    minHeight: 0,
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'flex-end',
  },
});

interface StyledHowWeDoItMetricShellProps {
  $interactive?: boolean;
}

export const StyledHowWeDoItMetricShell =
  styled.div<StyledHowWeDoItMetricShellProps>(({ $interactive = false }) => ({
    width: '100%',
    minWidth: 0,
    marginTop: 'auto',
    flex: '1 1 auto',
    minHeight: '120px',
    display: 'flex',
    flexDirection: 'column',
    padding: '24px',
    border: '1px solid #1414141f',
    borderRadius: '16px',
    background: '#FFFFFF',
    overflow: 'hidden',
    boxShadow: 'none',
    transition: 'background-color 300ms ease-out, box-shadow 300ms ease-out',

    [`& .innovation-home-how-we-do-it-big-number.bigNumberContainer`]: {
      padding: '0',
      gap: '12px',
      flex: 1,
      justifyContent: 'space-between',
      height: 'auto !important',

      '& > [class*="-orientation-vertical"]': {
        height: 'auto !important',
      },
    },

    [`& .innovation-home-how-we-do-it-big-number`]: {
      width: '100%',
      maxWidth: '100%',
      minWidth: 0,
      gap: '4px',
    },

    ...($interactive === true && {
      cursor: 'pointer',
      '&:hover': {
        background:
          'linear-gradient(0deg, rgba(229, 182, 17, 0.04) 0%, rgba(229, 182, 17, 0.04) 100%), #FFF',
        boxShadow: '0 0 8px 0 rgba(0, 0, 0, 0.16)',
      },
    }),
  }));
